package com.adc.application;

import com.adc.domain.performance.*;
import com.adc.domain.performance.QuarterlyCalculation.*;
import com.adc.domain.shared.*;
import com.adc.identity.IdentityGate;
import com.adc.infrastructure.*;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.json.JsonMapper;

@Service @Transactional(isolation=Isolation.READ_COMMITTED,rollbackFor=Exception.class)
public class QuarterlyPerformanceService implements ReceiptPolicy {
    public record ClosureEvidence(String clinic_id,String source_reference,String verification_reference,List<String> zero_cost_scope){}
    public record Preparation(String quarter_start,String quarter_end,String cutoff,List<String> clinic_ids,List<ClosureEvidence> closure_evidence,String personnel_verification_reference){}
    public record Calculate(String quarter_start,String quarter_end,String cutoff,List<String> clinic_ids,List<String> preparation_ids){}
    private final AtomicCommandExecutor commands;private final IdentityGate gate;private final QuarterlyPerformanceStore store;private final QuarterlySnapshotReader reader;private final BusinessRowLocks rows;private final Clock clock;private final AuditWriter audit;private static final JsonMapper JSON=JsonMapper.builder().enable(tools.jackson.core.json.JsonWriteFeature.WRITE_NUMBERS_AS_STRINGS).build();
    public QuarterlyPerformanceService(AtomicCommandExecutor commands,IdentityGate gate,QuarterlyPerformanceStore store,QuarterlySnapshotReader reader,BusinessRowLocks rows,Clock clock,AuditWriter audit){this.commands=commands;this.gate=gate;this.store=store;this.reader=reader;this.rows=rows;this.clock=clock;this.audit=audit;}
    public static String hash(Input input){return HexFormat.of().formatHex(Crypto.sha256(CanonicalJson.normalize(JSON.writeValueAsString(input))));}
    public static Input input(QuarterlyPerformanceStore.Row row){return JSON.readValue(JSON.readTree(row.snapshot()).get("input").toString(),Input.class);}
    public static String quarterLock(String start,String end){return TransactionLocks.name("performance-quarter",start+"/"+end);}
    public void access(IdentityGate.Identity actor,String capability,Collection<Long> clinics){for(long clinic:clinics)gate.requireStaff(actor,"HEADQUARTERS",capability,clinic);}
    private static String proof(String text){if(text==null || text.isBlank() || text.length()>255)throw new DomainFailure(422,"MISSING_VERIFICATION_REFERENCE");return text;}
    private String validate(String start,String end,String cutoff){QuarterlyPerformanceRules.quarter(start,end,clock.instant());var until=OffsetDateTime.parse(cutoff).toInstant();if(until.isAfter(clock.instant()) || until.isBefore(LocalDate.parse(end).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant()))throw new DomainFailure(422,"INVALID_QUARTER_CUTOFF");return until.toString();}
    private List<Long> clinics(List<String> ids){if(ids==null || ids.isEmpty())throw new DomainFailure(400,"INVALID_REQUEST");var clinics=ids.stream().map(BusinessValues::id).distinct().sorted().toList();if(clinics.size()!=ids.size())throw new DomainFailure(400,"INVALID_REQUEST");return clinics;}
    private Map<String,Object> response(Collection<Long> ids){var result=new LinkedHashMap<String,Object>();result.put("items",ids.stream().map(id->store.view(store.get(id,false))).toList());result.put("next_cursor",null);return result;}
    @Transactional(propagation=Propagation.MANDATORY)
    public AtomicCommandExecutor.Result saveFrozen(Input input,boolean calculate,String actor){
        var calculation=QuarterlyCalculation.calculate(input);rows.acquire(new BusinessRowLocks.Plan(new TreeSet<>(calculation.people().keySet()),Set.of(),Set.of()));String digest=hash(input);var snapshot=new LinkedHashMap<String,Object>();snapshot.put("rule_version","R1");snapshot.put("input",input);snapshot.put("input_hash",digest);snapshot.put("verified_by",input.preparer());var preparedAt=store.quarter(input.start(),input.end()).stream().filter(r->r.hash().equals(digest)).map(r->JSON.readTree(r.snapshot()).get("verified_at")).filter(n->n!=null && !n.isNull()).map(n->n.asText()).findFirst().orElse(clock.instant().toString());snapshot.put("verified_at",input.preparer()==null?null:preparedAt);snapshot.put("incomplete_reasons",calculation.reasons());snapshot.put("allocations",calculation.allocations());snapshot.put("calculated_by",calculate?actor:null);snapshot.put("calculated_at",calculate?clock.instant().toString():null);String status=calculate?(calculation.reasons().isEmpty()?"CALCULATED":"INCOMPLETE"):"DRAFT";var ids=new ArrayList<Long>();for(var person:calculation.people().entrySet())ids.add(store.save(person.getKey(),input,digest,JSON.writeValueAsString(snapshot),status,calculate?person.getValue():new Amounts(null,null,null,null,null),clock.instant()));return new AtomicCommandExecutor.Result(JSON.writeValueAsString(ids.stream().map(id->"QuarterlyPerformance:"+id).toList()),JSON.writeValueAsString(Map.of("performance_ids",ids.stream().map(String::valueOf).toList())),200,"QuarterlyPerformance",null,input.clinics(),null,input.personnelReference());
    }
    private Map<String,Object> completed(AtomicCommandExecutor.Command command,AtomicCommandExecutor.Result result){var actor=gate.authenticate(command.token(),command.client());authorize(actor,command.operation(),result.refs());var ids=new ArrayList<Long>();for(var id:JSON.readTree(result.summary()).get("performance_ids"))ids.add(BusinessValues.id(id.asText()));return response(ids);}
    public Map<String,Object> prepare(AtomicCommandExecutor.Command command,Preparation request)throws Exception{
        String cutoff=validate(request.quarter_start(),request.quarter_end(),request.cutoff());var clinics=clinics(request.clinic_ids());proof(request.personnel_verification_reference());if(request.closure_evidence()==null)throw new DomainFailure(400,"INVALID_REQUEST");var closures=new ArrayList<Closure>();var seen=new HashSet<Long>();for(var closure:request.closure_evidence()){long clinic=BusinessValues.id(closure.clinic_id());if(!clinics.contains(clinic) || !seen.add(clinic))throw new DomainFailure(422,"INVALID_CLOSURE_SCOPE");proof(closure.source_reference());proof(closure.verification_reference());var zero=closure.zero_cost_scope()==null?List.<String>of():closure.zero_cost_scope();if(!Set.of("MEDICAL_SUPPLY","OPERATING").containsAll(zero) || new HashSet<>(zero).size()!=zero.size())throw new DomainFailure(422,"INVALID_ZERO_COST_SCOPE");closures.add(new Closure(clinic,closure.source_reference(),closure.verification_reference(),zero.stream().sorted().toList()));}closures.sort(Comparator.comparingLong(Closure::clinic));
        return completed(command,commands.executeWithLocks(command,List.of(quarterLock(request.quarter_start(),request.quarter_end())),actor->access(actor,"cost.verify",clinics),actor->{var input=reader.capture(request.quarter_start(),request.quarter_end(),cutoff,clinics,closures,request.personnel_verification_reference(),actor.subjectId());access(actor,"cost.verify",input.clinics());return saveFrozen(input,false,actor.subjectId());}));
    }
    public Map<String,Object> calculate(AtomicCommandExecutor.Command command,Calculate request)throws Exception{
        String cutoff=validate(request.quarter_start(),request.quarter_end(),request.cutoff());var clinics=clinics(request.clinic_ids());return completed(command,commands.executeWithLocks(command,List.of(quarterLock(request.quarter_start(),request.quarter_end())),actor->access(actor,"performance.calculate",clinics),actor->{Input input=null;var ids=request.preparation_ids()==null?List.<String>of():request.preparation_ids();for(String id:ids){var row=store.get(BusinessValues.id(id),false);var frozen=input(row);if(!frozen.start().equals(request.quarter_start()) || !frozen.end().equals(request.quarter_end()) || !frozen.cutoff().equals(cutoff) || !frozen.clinics().containsAll(clinics) || frozen.preparer()==null || !hash(frozen).equals(row.hash()) || (input!=null && !hash(input).equals(row.hash())))throw new DomainFailure(422,"INCONSISTENT_PREPARATION_BATCH");input=frozen;}if(input==null)input=reader.capture(request.quarter_start(),request.quarter_end(),cutoff,clinics,List.of(),null,null);access(actor,"performance.calculate",input.clinics());return saveFrozen(input,true,actor.subjectId());}));
    }
    public Map<String,Object> sources(String token,String client,long id,String request){var failed=new IdentityGate.Identity[1];AuditWriter.onRollback(audit,()->failed[0],"getQuarterPerformanceSources",request);var actor=gate.authenticate(token,client);failed[0]=actor;var row=store.get(id,false);var input=input(row);for(String capability:List.of("sensitive.drilldown","cost.verify","getInvoice","resource.read"))access(actor,capability,input.clinics());audit.success(actor,"getQuarterPerformanceSources","QuarterlyPerformance",Long.toString(id),input.clinics(),request);return Map.of("quarterly_performance_id",Long.toString(id),"rule_version","R1","cutoff",input.cutoff(),"input_hash",row.hash(),"source_snapshot",JSON.readValue(row.snapshot(),Map.class));}
    private boolean canRead(IdentityGate.Identity actor,QuarterlyPerformanceStore.Row row){var scope=input(row).clinics();for(String capability:List.of("performance.calculate","performance.publish","cost.verify","analysis.read")){if(capability.equals("analysis.read") && !row.status().equals("PUBLISHED"))continue;try{var allowed=gate.staffClinics(actor,"HEADQUARTERS",capability);if(allowed.containsAll(scope))return true;}catch(DomainFailure denied){if(denied.status()!=403)throw denied;}}return false;}
    public Map<String,Object> list(String token,String client,String start,String end,String dentist,String status,String cursor,int limit,String request){var failed=new IdentityGate.Identity[1];AuditWriter.onRollback(audit,()->failed[0],"listQuarterPerformance",request);var actor=gate.authenticate(token,client);failed[0]=actor;if(limit<1 || limit>100 || (start==null)!=(end==null))throw new DomainFailure(400,"INVALID_REQUEST");boolean functional=false;for(String capability:List.of("performance.calculate","performance.publish","cost.verify","analysis.read"))try{gate.staffClinics(actor,"HEADQUARTERS",capability);functional=true;break;}catch(DomainFailure denied){if(denied.status()!=403)throw denied;}if(!functional)throw new DomainFailure(403,"ACCESS_DENIED");var all=start==null?store.all():store.quarter(start,end);long after=cursor==null?0:BusinessValues.id(cursor);var found=all.stream().filter(r->r.id()>after && (dentist==null || r.dentist()==BusinessValues.id(dentist)) && (status==null || r.status().equals(status)) && canRead(actor,r)).sorted(Comparator.comparingLong(QuarterlyPerformanceStore.Row::id)).limit(limit+1L).toList();var response=new LinkedHashMap<String,Object>();response.put("items",found.stream().limit(limit).map(store::view).toList());response.put("next_cursor",found.size()>limit?Long.toString(found.get(limit-1).id()):null);audit.success(actor,"listQuarterPerformance","QuarterlyPerformance",null,List.of(),request);return response;}
    @Override @Transactional(propagation=Propagation.NOT_SUPPORTED)public Set<String> operations(){return Set.of("prepareQuarterPerformance","calculateQuarterPerformance");}
    @Override public void authorize(IdentityGate.Identity actor,String operation,String refs){String capability=switch(operation){case "prepareQuarterPerformance"->"cost.verify";case "calculateQuarterPerformance"->"performance.calculate";default->throw new DomainFailure(403,"ACCESS_DENIED");};gate.staffClinics(actor,"HEADQUARTERS",capability);if(refs!=null)for(var ref:JSON.readTree(refs)){String value=ref.asText();if(!value.startsWith("QuarterlyPerformance:"))throw new DomainFailure(403,"ACCESS_DENIED");access(actor,capability,input(store.get(BusinessValues.id(value.substring(21)),false)).clinics());}}
}
